package com.example.userservice.service;

import com.example.userservice.model.User;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

/**
 * 用户服务层
 * 使用内存 Map 模拟数据库（简化示例，生产环境应使用 JPA/MyBatis）
 * 预置了 3 条测试数据
 */
@Service
public class UserService {

    // 模拟数据库：ConcurrentHashMap 保证线程安全
    private final Map<Long, User> userDatabase = new ConcurrentHashMap<>();
    // 自增 ID 生成器
    private final AtomicLong idGenerator = new AtomicLong(1);

    public UserService() {
        // 预置测试数据
        save(new User(null, "张三", "zhangsan@example.com", 28));
        save(new User(null, "李四", "lisi@example.com", 32));
        save(new User(null, "王五", "wangwu@example.com", 25));
    }

    /** 查询所有用户 */
    public List<User> findAll() {
        return new ArrayList<>(userDatabase.values());
    }

    /** 根据 ID 查询用户 */
    public Optional<User> findById(Long id) {
        return Optional.ofNullable(userDatabase.get(id));
    }

    /** 新增用户（自动分配 ID） */
    public User save(User user) {
        if (user.getId() == null) {
            user.setId(idGenerator.getAndIncrement());
        }
        userDatabase.put(user.getId(), user);
        return user;
    }

    /** 删除用户 */
    public boolean deleteById(Long id) {
        return userDatabase.remove(id) != null;
    }
}
