package com.example.consumer.feign;

import com.example.consumer.model.User;
import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.*;

import java.util.List;

/**
 * =====================================================
 * OpenFeign 声明式接口 - 本项目的核心亮点！
 * =====================================================
 *
 * 工作原理：
 * 1. @FeignClient(name = "user-service") 表示要调用的服务名
 *    → Feign 会通过 Eureka 查询 "user-service" 的地址列表
 *    → 再通过 LoadBalancer 选择一个实例发送 HTTP 请求
 *
 * 2. 接口中的方法签名要与被调用服务的 Controller 方法一一对应
 *    → @GetMapping("/api/users") 对应 UserController.listAll()
 *    → @GetMapping("/api/users/{id}") 对应 UserController.getById()
 *
 * 3. Feign 会在运行时自动生成代理对象，注入到 Spring 容器
 *    → 调用方只需 @Autowired 注入即可，像调用本地方法一样调用远程服务
 *
 * fallback：熔断降级（当 user-service 不可用时返回兜底数据）
 */
@FeignClient(
    name = "user-service",                    // 目标服务名（在 Eureka 中注册的名字）
    path = "/api/users",                      // 统一路径前缀
    fallback = UserServiceFallback.class      // 熔断降级实现类
)
public interface UserServiceFeignClient {

    /** 查询所有用户 */
    @GetMapping
    List<User> listAll();

    /** 根据 ID 查询用户 */
    @GetMapping("/{id}")
    User getById(@PathVariable("id") Long id);

    /** 新增用户 */
    @PostMapping
    User create(@RequestBody User user);

    /** 删除用户 */
    @DeleteMapping("/{id}")
    String delete(@PathVariable("id") Long id);
}
EOF

