package com.example.consumer.fallback;

import com.example.consumer.feign.UserServiceFeignClient;
import com.example.consumer.model.User;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.List;

/**
 * Feign 降级（Fallback）实现类
 *
 * 当 user-service 不可用（宕机、超时、网络异常）时：
 *   → 不会抛出异常让调用方崩溃
 *   → 而是返回这里的兜底数据，实现服务降级（优雅降级）
 *
 * 这是微服务架构中「容错设计」的重要手段
 * 生产环境通常会配合 Sentinel/Hystrix 做更细粒度的熔断控制
 */
@Component
public class UserServiceFallback implements UserServiceFeignClient {

    @Override
    public List<User> listAll() {
        // 返回降级数据：空列表
        return Collections.emptyList();
    }

    @Override
    public User getById(Long id) {
        // 返回降级数据：一个默认用户对象
        User fallbackUser = new User();
        fallbackUser.setId(-1L);
        fallbackUser.setName("服务不可用（降级返回）");
        fallbackUser.setEmail("N/A");
        return fallbackUser;
    }

    @Override
    public User create(User user) {
        // 降级时无法创建
        return null;
    }

    @Override
    public String delete(Long id) {
        return "服务不可用，删除失败（降级返回）";
    }
}
EOF

