package com.example.consumer.controller;

import com.example.consumer.feign.UserServiceFeignClient;
import com.example.consumer.model.User;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.util.List;

/**
 * 消费端控制器
 *
 * 演示如何通过 OpenFeign 调用远程的 user-service：
 *   → 不需要手动拼接 URL
 *   → 不需要 RestTemplate
 *   → 直接调用 Feign 接口方法，就像调用本地方法一样！
 *
 * 接口列表：
 *   GET    /consumer/users         → 通过 Feign 调用 user-service 查询所有用户
 *   GET    /consumer/users/{id}    → 通过 Feign 调用 user-service 根据 ID 查询
 *   POST   /consumer/users         → 通过 Feign 调用 user-service 新增用户
 *   GET    /consumer/test          → 测试连通性
 */
@RestController
@RequestMapping("/consumer")
public class ConsumerController {

    // 注入 Feign 代理对象（Spring 自动创建的代理，内部封装了 HTTP 调用逻辑）
    private final UserServiceFeignClient userFeignClient;

    @Autowired
    public ConsumerController(UserServiceFeignClient userFeignClient) {
        this.userFeignClient = userFeignClient;
    }

    /**
     * 查询所有用户
     * 内部流程：
     *   1. Feign → Eureka 查询 "user-service" 的实例列表
     *   2. LoadBalancer → 选择一个实例（如 http://192.168.1.10:8081）
     *   3. 发送 GET http://192.168.1.10:8081/api/users
     *   4. 反序列化 JSON 响应为 List<User>
     */
    @GetMapping("/users")
    public List<User> getAllUsers() {
        return userFeignClient.listAll();
    }

    /** 根据 ID 查询用户 */
    @GetMapping("/users/{id}")
    public User getUserById(@PathVariable Long id) {
        return userFeignClient.getById(id);
    }

    /** 新增用户 */
    @PostMapping("/users")
    public User createUser(@RequestBody User user) {
        return userFeignClient.create(user);
    }

    /** 删除用户 */
    @DeleteMapping("/users/{id}")
    public String deleteUser(@PathVariable Long id) {
        return userFeignClient.delete(id);
    }

    /** 测试端点：验证 consumer-service 自身是否正常运行 */
    @GetMapping("/test")
    public String test() {
        return "consumer-service 运行正常！正在通过 OpenFeign 调用 user-service...";
    }
}
